self.KB_CONTENT["card:792866"]={"id":"card:792866","ty":"card","sourceId":"792866","title":"『費用資料建立作業』的作業目的為何？","ver":"GP4以上","topic":"費用","keywords":["費用","開窗","出貨"],"y":"explain","answer":"可以輸入、查詢、修改、刪除出貨費用之相關資料，提供出口費用建立作業費用欄位開窗資料來源。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
